def store_secret(project: str, key_id: str, value: str, provider: str = "", purpose: str = "") -> str:
    """Store an encrypted secret for the project (Director only).

    Use this to save API keys, tokens, or passwords that the project needs.
    Values are encrypted at rest and only accessible via request_secret with user approval.

    Args:
        project: Project name.
        key_id: Unique identifier (e.g. "openai_key", "hf_token", "wandb_key").
        value: The secret value to store.
        provider: Service name (e.g. "OpenAI", "HuggingFace").
        purpose: What this key is used for.
    """
    result = secrets_mod.store_secret(project, key_id, value, provider, purpose)
    return _tool_result_to_str(result)


@mcp.tool()
def list_secrets(project: str) -> str:
    """List all stored secrets for the project (metadata only, no values).

    Shows key_id, provider, purpose — but never the actual secret value.
    Use request_secret to obtain the value (requires user approval).

    Args:
        project: Project name.
    """
    result = secrets_mod.list_secrets(project)
    return _tool_result_to_str(result)


@mcp.tool()
def check_credentials(services: list[str] | None = None) -> str:
    """Check credential status for feishu / ssh / wandb.

    Args:
        services: List of services to check. None = check all.
                  Valid values: "feishu", "ssh", "wandb".
    """
    from core.startup_checks import (
        check_feishu_credentials,
        check_ssh_config,
        check_wandb_config,
    )
    all_checks = {
        "feishu": check_feishu_credentials,
        "ssh":    check_ssh_config,
        "wandb":  check_wandb_config,
    }
    targets = services if services else list(all_checks.keys())
    unknown = [s for s in targets if s not in all_checks]
    if unknown:
        return _tool_result_to_str(ssh.ToolResult(
            success=False, error=f"Unknown services: {unknown}. Valid: {list(all_checks)}",
        ))

    lines = []
    all_passed = True
    for name in targets:
        result = all_checks[name]()
        status = "✓" if result.passed else "✗"
        lines.append(f"{status} {name}: {result.message}")
        if not result.passed:
            all_passed = False

    return _tool_result_to_str(ssh.ToolResult(
        success=all_passed, data={"output": "\n".join(lines)},
    ))


@mcp.tool()
def delete_secret(project: str, key_id: str) -> str:
    """Delete a stored secret (Director only).

    Args:
        project: Project name.
        key_id: Secret identifier to delete.
    """
    result = secrets_mod.delete_secret(project, key_id)
    return _tool_result_to_str(result)


